package io.github.dream07code.innovationspace.points;
import io.github.dream07code.innovationspace.common.api.*;import io.github.dream07code.innovationspace.security.SessionPrincipal;import io.github.dream07code.innovationspace.member.MemberScopePolicy;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;@Service public class PointLedgerService{private final JdbcTemplate jdbc;public PointLedgerService(JdbcTemplate j){jdbc=j;}public long total(long member){return jdbc.queryForObject("SELECT COALESCE(SUM(delta),0) FROM point_ledger WHERE member_id=?",Long.class,member);}public Map<String,Object> ledger(long member,int page,int size,SessionPrincipal p){if(p.memberId()!=null&&p.memberId()!=member&&!"COLLEGE_ADMIN".equals(p.role()))throw new io.github.dream07code.innovationspace.common.exception.ApiException(403,ErrorCode.FORBIDDEN);var rows=jdbc.queryForList("SELECT * FROM point_ledger WHERE member_id=? ORDER BY recorded_at DESC,id DESC LIMIT ? OFFSET ?",member,size,(page-1)*size);return Map.of("items",rows,"page",page,"size",size,"total",jdbc.queryForObject("SELECT COUNT(*) FROM point_ledger WHERE member_id=?",Long.class,member));}}
